#!/usr/bin/env python3
"""T5 patch — installs vector retrieval into GraphRAG.

1. Creates src/evidence/vector_retrieval.py (hashed-TF-IDF vector index over
   the 5,565 closed cases; cosine top-k retrieval).
2. Patches src/evidence/graphrag.py:
   - GraphRAGSynthesizer.__init__ builds a CaseVectorIndex from graph data
   - build_investigation_context gains section 7 (vector-retrieved precedents)
Idempotent. Verify afterwards with:  python -m pytest tests -k vector
"""
import base64
import sys
from pathlib import Path

ROOT = Path(__file__).parent.parent
VEC_PATH = ROOT / "src" / "evidence" / "vector_retrieval.py"
GRAPH_PATH = ROOT / "src" / "evidence" / "graphrag.py"

VECTOR_B64 = ""

REPLACEMENTS = [
    ('    def __init__(self, graph: InMemoryGraph):\n        self.graph = graph\n', '    def __init__(self, graph: InMemoryGraph, vector_index: Optional["CaseVectorIndex"] = None):\n        self.graph = graph\n        if vector_index is not None:\n            self.vector_index = vector_index\n        else:\n            from .vector_retrieval import CaseVectorIndex\n            cases: list[ClosedCase] = []\n            for c in graph.vertices.get("ClosedCase", {}).values():\n                if isinstance(c, ClosedCase):\n                    cases.append(c)\n                elif isinstance(c, dict):\n                    try:\n                        cases.append(ClosedCase(\n                            case_id=c.get("case_id", ""),\n                            customer_id=c.get("customer_id", ""),\n                            card_id=c.get("card_id", ""),\n                            opened_at=c.get("opened_at", ""),\n                            closed_at=c.get("closed_at", ""),\n                            outcome=c.get("outcome", ""),\n                            pattern=c.get("pattern", "none"),\n                            analyst_notes=c.get("analyst_notes", ""),\n                            actions_taken=c.get("actions_taken", ""),\n                            exposure_usd=float(c.get("exposure_usd", 0) or 0),\n                            n_txns=int(c.get("n_txns", 0) or 0),\n                        ))\n                    except Exception:\n                        continue\n            self.vector_index = CaseVectorIndex(cases) if cases else None\n'),
    ('        # 6. Graph-level signals\n        sections.append(self._section_graph_signals(state))\n\n        return "\\n\\n".join(s for s in sections if s)\n', '        # 6. Graph-level signals\n        sections.append(self._section_graph_signals(state))\n\n        # 7. Vector retrieval over prior cases (T5 GraphRAG)\n        sections.append(self._section_vector_case_memory(state))\n\n        return "\\n\\n".join(s for s in sections if s)\n'),
    ('    def _section_graph_signals(self, state: InvestigationState) -> str:\n', '    def _section_vector_case_memory(self, state: InvestigationState) -> str:\n        """T5: semantic retrieval of similar prior cases via vector search.\n\n        Unlike _section_case_memory (entity overlap: same card/customer), this\n        retrieves cases that are textually/semantically similar to the current\n        investigation profile even when no entity is shared.\n        """\n        if self.vector_index is None or len(self.vector_index) == 0:\n            return ""\n        try:\n            from .vector_retrieval import investigation_text\n            query = investigation_text(state)\n            hits = self.vector_index.search(query, k=4)\n        except Exception as e:\n            logger.warning("Vector retrieval failed: %s", e)\n            return ""\n        if not hits:\n            return ""\n\n        lines = [\n            "## Similar Prior Cases (vector retrieval)",\n            f"Top-{len(hits)} cosine matches over {len(self.vector_index)} embedded "\n            "closed cases (hashed TF-IDF, IDF-weighted, L2-normalised):\\n",\n        ]\n        for case, score in hits:\n            lines.append(f"### {case.case_id} (cosine={score:.3f})")\n            lines.append(f"- Outcome: {case.outcome} | Pattern: {case.pattern} | "\n                         f"Exposure: ${case.exposure_usd:.2f} | Txns: {case.n_txns}")\n            if case.analyst_notes:\n                lines.append(f"- Analyst notes: {case.analyst_notes[:180]}")\n            lines.append("")\n        lines.append(\n            "Use these precedents to calibrate the verdict: if the current evidence "\n            "profile closely matches confirmed_fraud precedents, raise confidence; "\n            "if it matches cleared precedents, lower it.")\n        return "\\n".join(lines)\n\n    def _section_graph_signals(self, state: InvestigationState) -> str:\n'),
]


def main():
    VEC_PATH.write_text(base64.b64decode(VECTOR_B64).decode("utf-8"), encoding="utf-8")
    print("wrote", VEC_PATH)

    src = GRAPH_PATH.read_text(encoding="utf-8")
    if "_section_vector_case_memory" in src and "vector_index" in src:
        print("graphrag.py already patched — leaving as is.")
    else:
        for i, (old, new) in enumerate(REPLACEMENTS, 1):
            if old not in src:
                print(f"ERROR: replacement {i} not found in graphrag.py — aborting.")
                sys.exit(1)
            src = src.replace(old, new, 1)
        GRAPH_PATH.write_text(src, encoding="utf-8")
        print("patched", GRAPH_PATH)

    import py_compile
    py_compile.compile(str(VEC_PATH), doraise=True)
    py_compile.compile(str(GRAPH_PATH), doraise=True)
    print("Compiles OK.")
    print("Next: set the evaluator key in .env, then  python main.py investigate")


if __name__ == "__main__":
    main()